    padding: 0.5rem 1rem;
    border-left: 0.1rem solid var(--gpo-theme-border);
    border-radius: 0;
    color: var(--gpo-theme-muted);
    background: var(--gpo-theme-soft-bg);
    font-size: var(--gpo-theme-font-size);
}

/* Phone country list stays outside the painted input wrapper */

.gpo-app .iti {
    min-height: 0;
    border-radius: var(--border-radius-input);
}

.gpo-app .iti__flag-container {
    padding: 0;
}

.gpo-app .iti--separate-dial-code .iti__selected-flag {
    color: var(--gpo-theme-text);
    background: var(--gpo-theme-soft-bg);
}

/* A content-sized list avoids the plugin shrinking it to the dial-code button on mobile */

.gpo-app .iti__country-list {
    width: max-content;
    min-width: min(30rem, calc(100vw - 4rem));
    max-width: calc(100vw - 4rem);
    border-color: var(--gpo-theme-border);
    border-radius: var(--gpo-theme-radius);
    color: var(--gpo-theme-text);
    background: var(--gpo-theme-bg);
    box-shadow: none;
    font-size: var(--gpo-theme-font-size);
}

.gpo-app .gpo-color-box .preview-btn {
    border-radius: var(--border-radius-input);
}

.gpo-app .gpo-color-box .gpo-color {
    padding-left: 6.8rem;
}

/* File upload */

.gpo-app .gpo-dropzone {
    border: 0.1rem dashed var(--gpo-theme-border);
    border-radius: var(--border-radius-input);
    background: transparent;
    transition: border-color var(--duration-default);
}

.gpo-app .gpo-dropzone:hover,
.gpo-app .gpo-dropzone:focus-within {
    border-color: var(--gpo-theme-text) !important;
    background: transparent;
}

/* Action: like .button--primary, including its vertical hover fill */

.gpo-app .gpo-dropzone__action {
    position: relative;
    z-index: 0;
    overflow: hidden;
    align-items: center;
    justify-content: center;
    min-height: 4rem;
    padding: 0.9rem 1.8rem;
    border: 0;
    border-radius: var(--border-radius-button);
    color: rgb(var(--color-button-text));
    background: var(--gpo-theme-accent);
    font-family: var(--font-button-family);
    font-size: calc(var(--font-button-scale) * 1rem);
    font-style: var(--font-button-style);
    font-weight: var(--font-button-weight);
    letter-spacing: var(--font-button-letter-spacing);
    line-height: 1.5;
    text-transform: var(--font-button-text-transform);
    transition: color 0.4s cubic-bezier(0.86, 0, 0.07, 1);
}

.gpo-app .gpo-dropzone__action::before {
    content: "";
    position: absolute;
    z-index: -1;
    inset: 0;
    border-radius: inherit;
    background: rgb(var(--color-button-hover));
    transform: scaleY(0);
    transform-origin: 0 0;
    transition: transform 0.4s cubic-bezier(0.86, 0, 0.07, 1);
}

.gpo-app .gpo-dropzone:hover .gpo-dropzone__action,
.gpo-app .gpo-dropzone:focus-within .gpo-dropzone__action {
    color: rgb(var(--color-button-text-hover));
}

.gpo-app .gpo-dropzone:hover .gpo-dropzone__action::before,
.gpo-app .gpo-dropzone:focus-within .gpo-dropzone__action::before {
    transform: scaleY(1);
    transform-origin: 100% 100%;
}

@media screen and (min-width: 576px) {
    .gpo-app .gpo-dropzone__action {
        padding-inline: 3.6rem;
    }
}

.gpo-app .gpo-dropzone__caption {
    color: var(--gpo-theme-muted);
    font-size: calc(var(--font-body-scale) * 1.2rem);
}

.gpo-app .gpo-f-card,
.gpo-app .gpo-uploading {
    border: 0.1rem solid var(--gpo-theme-border);
    border-radius: var(--border-radius-input);
    color: var(--gpo-theme-text);
    background: var(--gpo-theme-bg);
}

.gpo-app .gpo-f-link,
.gpo-app .gpo-f-name {
    color: var(--gpo-theme-text);
    font-size: var(--gpo-theme-font-size);
    line-height: var(--font-body-line-height);
}

.gpo-app .gpo-f-link img {
    border: 0;
    border-radius: var(--border-radius-input);
}

/* Remove: .button--secondary colors */

.gpo-app .gpo-f-rm {
    border: 1px solid rgb(var(--color-button-secondary));
    border-radius: var(--border-radius-button);
    color: rgb(var(--color-button-secondary-text));
    background: transparent;
    box-shadow: none;
}

.gpo-app .gpo-f-rm:hover {
    color: rgb(var(--color-button-secondary-text-hover));
    background: rgb(var(--color-button-secondary-hover));
}

/* Switch: theme-token adaptation; no native product switch */

.gpo-app .gpo-switch input + label span {
    color: var(--gpo-theme-text);
    font-size: var(--gpo-theme-font-size);
}

.gpo-app .gpo-switch input + label::before {
    background: var(--gpo-theme-soft-bg);
}

.gpo-app .gpo-switch input:checked + label::before {
    background: var(--gpo-theme-accent);
}

.gpo-app .gpo-switch input + label::after {
    background: var(--gpo-theme-bg);
    box-shadow: 0 0 0 0.1rem var(--gpo-theme-border);
}

/* Range: theme-token adaptation; no native product range */

.gpo-app .gpo-range-tooltip {
    color: var(--gpo-theme-bg);
    background: var(--gpo-theme-text);
    border-radius: var(--border-radius-input);
    font-size: calc(var(--font-body-scale) * 1.2rem);
}

.gpo-app .gpo-range-tooltip::after {
    border-top-color: var(--gpo-theme-text);
}

.gpo-app .gpo-range-min,
.gpo-app .gpo-range-max {
    color: var(--gpo-theme-muted);
    font-size: calc(var(--font-body-scale) * 1.2rem);
}

.gpo-app .gpo-range .gpo-range-input::-webkit-slider-runnable-track {
    background: linear-gradient(to right, var(--gpo-theme-accent) var(--progress), var(--gpo-theme-soft-bg) var(--progress));
}

.gpo-app .gpo-range .gpo-range-input::-moz-range-track {
    background: var(--gpo-theme-soft-bg);
}

.gpo-app .gpo-range .gpo-range-input::-moz-range-progress {
    background: var(--gpo-theme-accent);
}

.gpo-app .gpo-range .gpo-range-input::-moz-range-thumb {
    background: var(--gpo-theme-accent);
}

.gpo-app .gpo-range .gpo-range-input::-webkit-slider-thumb {
    background: var(--gpo-theme-accent);
}

/* Tabs: typography of .product-accordion__toggle; retain GPO panel visibility */

.gpo-app .gpo-tabs .gpo-tabs-title .gpo-tabs-tab {
    color: var(--gpo-theme-text);
    font-family: var(--font-button-family);
    font-size: calc(var(--font-button-scale) * 1rem);
    font-weight: var(--font-button-weight);
    letter-spacing: var(--font-button-letter-spacing);
    line-height: 1.5;
}

.gpo-app .gpo-tabs .gpo-tabs-tabpanel .gpo-tabs-tabcontent {
    border: 0;
    border-radius: 0;
    color: var(--gpo-theme-text);
    background: transparent;
    font-size: var(--gpo-theme-font-size);
    line-height: var(--font-body-line-height);
}

/* Horizontal: variant-button styling as a fallback; no product tabs rendered */

.gpo-app .gpo-tabs:not(.gpo-tabs-vertical) .gpo-tabs-title .gpo-tabs-tab {
    margin: 0 0.8rem 0.8rem 0;
    padding: 0.9rem 1rem;
    border: 0;
    border-radius: var(--gpo-theme-swatch-radius);
    color: var(--gpo-theme-text);
    background: var(--gpo-theme-soft-bg);
    white-space: normal;
    transition: background-color var(--duration-default);
}

.gpo-app .gpo-tabs:not(.gpo-tabs-vertical) .gpo-tabs-title .gpo-tabs-tab:hover {
    background: var(--gpo-theme-border);
}

.gpo-app .gpo-tabs:not(.gpo-tabs-vertical) .gpo-tabs-title .gpo-tabs-tab.gpo-tab-active {
    color: rgb(var(--color-button-text));
    background: var(--gpo-theme-accent);
}

.gpo-app .gpo-tabs:not(.gpo-tabs-vertical) .gpo-tabs-tabpanel .gpo-tabs-tabcontent {
    padding: 1rem 0;
}

/* Vertical: .product-accordion__toggle with plus / minus icon */

.gpo-app .gpo-tabs.gpo-tabs-vertical {
    border: 0;
    border-radius: 0;
    background: transparent;
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab,
.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab.gpo-tab-active {
    flex-direction: row;
    justify-content: space-between;
    margin: 0;
    padding: 0 0 0.4rem;
    border: 0;
    border-radius: 0;
    color: var(--gpo-theme-text);
    background: transparent;
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab::before {
    display: none;
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab::after {
    content: "+";
    flex: 0 0 1.8rem;
    font-size: 1.8rem;
    font-weight: 400;
    line-height: 1;
    text-align: center;
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab.gpo-tab-active::after {
    content: "−";
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-tabpanel .gpo-tabs-tabcontent {
    padding: 1rem 0 2rem;
}

